#define WIN32_LEAN_AND_MEAN
#include "protected_output_acl.h"
#include <aclapi.h>

namespace stellar::discovery { namespace {
struct Sid{PSID value{};~Sid(){if(value)FreeSid(value);}};
bool MakeSid(BYTE count,DWORD a,DWORD b,Sid&out){SID_IDENTIFIER_AUTHORITY nt=SECURITY_NT_AUTHORITY;return AllocateAndInitializeSid(&nt,count,a,b,0,0,0,0,0,0,&out.value)!=FALSE;}
bool AllowedSid(PSID candidate,PSID approved,PSID system,PSID admins){return IsValidSid(candidate)&&(EqualSid(candidate,system)||EqualSid(candidate,admins)||(approved&&IsValidSid(approved)&&EqualSid(candidate,approved)));}
bool AceParts(void*raw,BYTE type,ACCESS_MASK&mask,PSID&sid){auto*header=static_cast<ACE_HEADER*>(raw);if(header->AceSize<sizeof(ACE_HEADER)+sizeof(ACCESS_MASK)+sizeof(DWORD))return false;if(type==ACCESS_ALLOWED_ACE_TYPE||type==ACCESS_DENIED_ACE_TYPE){auto*ace=static_cast<ACCESS_ALLOWED_ACE*>(raw);mask=ace->Mask;sid=&ace->SidStart;return IsValidSid(sid)&&GetLengthSid(sid)<=header->AceSize-(reinterpret_cast<BYTE*>(sid)-reinterpret_cast<BYTE*>(raw));}if(type==ACCESS_ALLOWED_OBJECT_ACE_TYPE||type==ACCESS_DENIED_OBJECT_ACE_TYPE){auto*ace=static_cast<ACCESS_ALLOWED_OBJECT_ACE*>(raw);mask=ace->Mask;BYTE*p=reinterpret_cast<BYTE*>(&ace->ObjectType);if(ace->Flags&ACE_OBJECT_TYPE_PRESENT)p+=sizeof(GUID);if(ace->Flags&ACE_INHERITED_OBJECT_TYPE_PRESENT)p+=sizeof(GUID);sid=p;return p<reinterpret_cast<BYTE*>(raw)+header->AceSize&&IsValidSid(sid)&&GetLengthSid(sid)<=header->AceSize-(p-reinterpret_cast<BYTE*>(raw));}return false;}
}
bool ProtectedOutputAclAllowed(PSECURITY_DESCRIPTOR descriptor,PSID approved,std::string&error){if(!descriptor||!IsValidSecurityDescriptor(descriptor)){error="invalid security descriptor";return false;}PSID owner{};BOOL ownerDefault{};if(!GetSecurityDescriptorOwner(descriptor,&owner,&ownerDefault)||!owner){error="missing owner";return false;}BOOL present{},defaulted{};PACL dacl{};if(!GetSecurityDescriptorDacl(descriptor,&present,&dacl,&defaulted)||!present||!dacl||!IsValidAcl(dacl)){error="null or invalid dacl";return false;}Sid system{},admins{};if(!MakeSid(1,SECURITY_LOCAL_SYSTEM_RID,0,system)||!MakeSid(2,SECURITY_BUILTIN_DOMAIN_RID,DOMAIN_ALIAS_RID_ADMINS,admins)){error="allowlist sid creation failed";return false;}if(!AllowedSid(owner,approved,system.value,admins.value)){error="owner not allowlisted";return false;}GENERIC_MAPPING mapping{FILE_GENERIC_READ,FILE_GENERIC_WRITE,FILE_GENERIC_EXECUTE,FILE_ALL_ACCESS};constexpr ACCESS_MASK dangerous=FILE_WRITE_DATA|FILE_APPEND_DATA|FILE_WRITE_EA|FILE_WRITE_ATTRIBUTES|FILE_DELETE_CHILD|DELETE|WRITE_DAC|WRITE_OWNER;for(DWORD i=0;i<dacl->AceCount;++i){void*raw{};if(!GetAce(dacl,i,&raw)){error="ace read failed";return false;}auto*header=static_cast<ACE_HEADER*>(raw);ACCESS_MASK mask{};PSID sid{};if(!AceParts(raw,header->AceType,mask,sid)){error="unsupported or malformed ace";return false;}MapGenericMask(&mask,&mapping);const bool isAllow=header->AceType==ACCESS_ALLOWED_ACE_TYPE||header->AceType==ACCESS_ALLOWED_OBJECT_ACE_TYPE;const bool isDeny=header->AceType==ACCESS_DENIED_ACE_TYPE||header->AceType==ACCESS_DENIED_OBJECT_ACE_TYPE;if(!isAllow&&!isDeny){error="unsupported ace";return false;}if(isAllow&&(mask&dangerous)&&!AllowedSid(sid,approved,system.value,admins.value)){error="untrusted sid has mutation authority";return false;}}
  return true;
}
bool ProtectedOutputHandleAllowed(HANDLE directory,PSID approved,std::string&error){PSECURITY_DESCRIPTOR descriptor{};PSID owner{};PACL dacl{};DWORD status=GetSecurityInfo(directory,SE_FILE_OBJECT,OWNER_SECURITY_INFORMATION|DACL_SECURITY_INFORMATION,&owner,nullptr,&dacl,nullptr,&descriptor);if(status!=ERROR_SUCCESS){error="security read failed:"+std::to_string(status);return false;}const bool accepted=ProtectedOutputAclAllowed(descriptor,approved,error);LocalFree(descriptor);return accepted;}
}
